insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'hero', 'Home: hero', 'Patna · Since 1984', 'Your home, your story.', 'Curtains, floors, walls and furniture — chosen with you and fitted by our own team, the way we''ve furnished homes and businesses across Patna for over forty years.', '/images/brochure/hero-bedroom.webp', 'Sunlit bedroom with a rust velvet bed and sheer curtains', 'Explore products', '/products', '[]'::jsonb, 1) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'story', 'Home: story strip', 'Since 1984', 'Furnishing relationships, not just rooms.', 'What began in 1984 as a furnishing shop on S.P. Verma Road now dresses homes, hotels, hospitals, schools and offices across Bihar — from the first measurement to the final fitting.', null, null, null, null, '[]'::jsonb, 2) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'philosophy', 'Home: philosophy teaser', 'Our philosophy', 'Every home is made of five elements.', 'Earth, water, fire, air and space — the five elements we furnish, so a room feels not just finished, but in balance.', null, null, 'Explore the philosophy', '/philosophy', '[]'::jsonb, 3) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'categories', 'Home: categories heading', 'What we do', 'Everything your space needs, in one place.', null, null, null, 'Browse all products', '/products', '[]'::jsonb, 4) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'sectors', 'Home: sectors heading', 'Where we work', 'From quiet homes to busy hospitals.', 'The same care and craft, scaled to the space.', null, null, 'See our expertise', '/expertise', '[]'::jsonb, 5) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('home', 'cta', 'Home: enquiry banner', null, 'Let''s bring your space to life.', 'Tell us what you''re planning. We''ll visit, measure and suggest options that suit your space and your budget.', '/images/brochure/why-dining.webp', 'Dining corner with ceramic pendant lamps', 'Make an enquiry', '/contact', '[]'::jsonb, 6) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'intro', 'About: introduction', 'About us', 'Furnishing homes and businesses since 1984.', 'New Ankur Furnishers began as a furnishing shop in the heart of Patna, and has spent four decades doing one thing well: helping people create spaces that feel like home.
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'why', 'About: why choose us', null, 'Why choose us', null, '/images/brochure/why-dining.webp', 'Dining corner with ceramic pendant lamps', null, null, '[{"title":"Four decades of experience","text":"Furnishing homes and businesses across Bihar since 1984."},{"title":"Fitted by our own team","text":"From measurement to installation, handled start to finish — no loose ends."},{"title":"Materials you can trust","text":"Honest, hard-wearing materials chosen to last, not just to look good on day one."},{"title":"Priced for real budgets","text":"Options at every price point, with honest advice on what''s worth it."}]'::jsonb, 2) on conflict (page, key) do nothing;
insert into public.page_sections (page, key, label, eyebrow, heading, body, image_url, image_alt, cta_label, cta_href, items, sort) values ('about', 'founder', 'About: founder''s note', 'From our founder', 'Forty years of furnishing relationships.', 'For us, a home is not just a place but a feeling — where the presence of loved ones becomes comfort, where relationships breathe, and where dreams take shape.
